package com.haucheng.erp.service;
import com.haucheng.erp.common.*; import com.haucheng.erp.dto.ProductRequest; import com.haucheng.erp.entity.MdProduct; import com.haucheng.erp.exception.BusinessException; import com.haucheng.erp.mapper.*; import com.haucheng.erp.vo.ProductView; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal;
@Service @RequiredArgsConstructor public class ProductService {
 private final ProductMapper mapper; private final CategoryMapper categoryMapper; private final UnitMapper unitMapper; private final BrandMapper brandMapper; private final OperationLogService operationLog; private final AssetDeviceMapper deviceMapper; private final StockMapper stockMapper;
 public PageResult<ProductView> getPage(String code,String name,Long categoryId,Long brandId,String model,Boolean status,String productType,Integer page,Integer size){Pagination p=Pagination.of(page,size);return new PageResult<>(mapper.selectPage(code,name,categoryId,brandId,model,status,productType,p),p.page(),p.size(),mapper.count(code,name,categoryId,brandId,model,status,productType));}
 public ProductView getById(Long id){ProductView v=mapper.selectViewById(id);if(v==null)throw BusinessException.notFound("物资不存在");return v;}
 @Transactional public ProductView create(ProductRequest r){String code=r.getProductCode().trim(),name=r.getProductName().trim();if(mapper.countByCode(code,null)>0)throw BusinessException.conflict("物资编号已存在");validateReferences(r);validateStock(r);MdProduct e=build(r,code,name);mapper.insert(e);operationLog.record("PRODUCT_CREATE",String.valueOf(e.getId()),"创建物资");return getById(e.getId());}
 @Transactional public ProductView update(Long id,ProductRequest r){MdProduct old=require(id);String code=r.getProductCode().trim(),name=r.getProductName().trim();if(mapper.countByCode(code,id)>0)throw BusinessException.conflict("物资编号已存在");validateReferences(r);validateStock(r);validateCoreAttributes(old,r);MdProduct e=build(r,code,name);e.setId(id);mapper.update(e);operationLog.record("PRODUCT_UPDATE",String.valueOf(id),"修改物资");return getById(id);}
 @Transactional public void updateStatus(Long id,Boolean status){require(id);mapper.updateStatus(id,status);operationLog.record(status?"PRODUCT_ENABLE":"PRODUCT_DISABLE",String.valueOf(id),status?"启用物资":"停用物资");}
 private void validateCoreAttributes(MdProduct old,ProductRequest r){if(stockMapper.countProductReferences(old.getId())>0 && (!old.getProductType().equals(r.getProductType()) || !old.getUnitId().equals(r.getUnitId())))throw BusinessException.conflict("物资已有库存或库存单据，不能修改类型和计量单位");if(deviceMapper.countByProduct(old.getId())>0 && (!old.getProductType().equals(r.getProductType()) || !old.getTrackSn().equals(Boolean.TRUE.equals(r.getTrackSn())) || !old.getTrackMac().equals(Boolean.TRUE.equals(r.getTrackMac())) || !old.getIsFixedAsset().equals(Boolean.TRUE.equals(r.getIsFixedAsset()))))throw BusinessException.conflict("物资已有设备实例，不能修改设备类型或设备身份管理属性");}
 private void validateReferences(ProductRequest r){if(categoryMapper.countActive(r.getCategoryId())==0)throw BusinessException.badRequest("分类不存在或已停用");if(unitMapper.countActive(r.getUnitId())==0)throw BusinessException.badRequest("单位不存在或已停用");if(brandMapper.countActive(r.getBrandId())==0)throw BusinessException.badRequest("品牌不存在或已停用");}
 private void validateStock(ProductRequest r){if(r.getMinStock().compareTo(r.getMaxStock())>0)throw BusinessException.badRequest("最低库存不能高于最高库存");if(r.getSafetyStock().compareTo(r.getMaxStock())>0)throw BusinessException.badRequest("安全库存不能高于最高库存");}
 private MdProduct require(Long id){MdProduct e=mapper.selectByIdForUpdate(id);if(e==null)throw BusinessException.notFound("物资不存在");return e;}
 private MdProduct build(ProductRequest r,String code,String name){MdProduct e=new MdProduct();e.setProductCode(code);e.setProductName(name);e.setCategoryId(r.getCategoryId());e.setBrandId(r.getBrandId());e.setModel(trim(r.getModel()));e.setSpecification(trim(r.getSpecification()));e.setUnitId(r.getUnitId());e.setProductType(r.getProductType());e.setTrackSn(Boolean.TRUE.equals(r.getTrackSn()));e.setTrackMac(Boolean.TRUE.equals(r.getTrackMac()));e.setIsFixedAsset(Boolean.TRUE.equals(r.getIsFixedAsset()));e.setEnableQrcode(Boolean.TRUE.equals(r.getEnableQrcode()));e.setSafetyStock(r.getSafetyStock());e.setMinStock(r.getMinStock());e.setMaxStock(r.getMaxStock());e.setRemark(trim(r.getRemark()));e.setStatus(r.getStatus()==null||r.getStatus());return e;} private String trim(String value){return value==null?null:value.trim();}
}
